    public static Object[] clearNull(final Object[] arr) {
        ArrayList<Object> list = new ArrayList<Object>();
        if (arr != null) {
            for (Object item : arr) {
                if (item != null) {
                    list.add(item);
                }
            }
        }
        return list.toArray();
    }
}

