        if (currentLength + 2 > data.length) {
            enlarge(2);
        }
        byte[] currentData = data;
        currentData[currentLength++] = (byte) (shortValue >>> 8);
        currentData[currentLength++] = (byte) shortValue;
        length = currentLength;
        return this;
