    private void initServletProcessor(AtmosphereHandler h) {
        if (!isInit) return;

        try {
            if (h instanceof AtmosphereServletProcessor) {
                ((AtmosphereServletProcessor) h).init(config);
            }
        } catch (ServletException e) {
            throw new RuntimeException(e);
        }
    }

