                    ",\n\t transport=" + transport() +
                    ",\n\t isInScope=" + isInScope +
                    ",\n\t isResumed=" + isResumed() +
                    ",\n\t isCancelled=" + isCancelled() +
                    ",\n\t isSuspended=" + isSuspended() +
